import * as React from "react";

export type MouseIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function MouseIcon({ size = 20, ...props }: MouseIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="8" y="3.5" width="8" height="17" rx="4" /><path d="M12 3.5 L12 9 M12 6.5 L12.1 6.5" />
    </svg>
  );
}
